using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Foundation;

internal sealed class OriginalReturnSectorsDocument : IScribeDocumentDefinition
{
    private const string Owner = "D5/S3/Quantum/Foundation/OriginalReturnSectors.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Uniform sectors and intrinsic singular-tail mass for whole original returns.",
        H("Original return sectors and singular tails"), Blocks(
        Paragraph(Text("V is the original finite dimensional real space, C is its closed pointed generating cone, and u is strictly positive on every nonzero cone vector. K is the entire normalized base C intersected with u=1, P consists of all its extreme points, and effects range over the entire interval [0,u]. Every original exclusion D(p) is the image of a whole closed Euclidean unit ball under an injective affine chart of positive dimension. Dimensions may vary and may equal one. Fix any source F=D(p), any y in ri(F), and any whole injective source chart. No singleton-label, injective-label, distinguishable-frame, Pair, closed-pure-locus or common-dimension assumption is imposed.")),
        Describe.Lean(DescribeId.Create("leakage"), DeclarationHandle.Create(Owner + "leakage"),
            H("Entire return leakage"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("alpha_F(t) is the supremum of dist(x,F) over every x in D(t). Compactness makes it an attained maximum. The same auxiliary norm is used throughout. No selected subset of a return face is substituted."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("base-maximum"), DeclarationHandle.Create(Owner + "baseMaximum"),
            H("Actual original maximum"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("M(b) is the supremum of b on the entire original K. For every nonzero original positive annihilator of an actual pure label, M(b)>0 and one fixed A>0 gives norm(b)<=A M(b). Normalize by the positive global maximum, apply the old full-cone bound to obtain an original effect, then use compactness of the entire effect interval in the original dual. M(b) has no imposed upper budget."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("whole-return-leakage"), DeclarationHandle.Create(Owner + "whole_return_leakage"),
            H("Uniform leakage for all actual returns"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(
                Paragraph(Text("For every delta>0 there is epsilon>0, chosen before r and t, such that pure r,t with dist(r,y)<epsilon and t in D(r) satisfy alpha_F(t)<delta. Original zero symmetry gives r in D(t). This controls the entire return face and permits repeated label fibers.")),
                Paragraph(Text("A contrary sequence supplies actual r_n tending to y, t_n in D(r_n), x_n in D(t_n) a fixed positive distance from F, and original common confirming effects e_n vanishing on all of D(t_n). Joint compactness of K, K and the full effect interval gives a common limit (t,x,e). Evaluation continuity gives e(y)=e(x)=0 and e(t)=1. The limiting label t is only asserted to belong to K.")),
                Paragraph(Text("The open source ball maps exactly onto ri(F). Nonnegativity of e on the entire source ball and its zero at an interior parameter force its restriction slope to vanish. Thus F lies in the zero face of e. This face is proper because e(t)=1. The old classification of all original proper faces and whole-ball facial rigidity identify it with F, so x belongs to F, contradicting the distance bound. No purity or uniqueness of a limiting label is used."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("source-contact-simplex"), DeclarationHandle.Create(Owner + "source_contact_simplex"),
            H("Actual contacts around every source interior point"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(
                Paragraph(Text("The supplied source chart yields an actual xi with a(xi)=y and norm(xi)<1. There are dim(a)+1 unit parameter vertices forming an affine basis, with every barycentric coordinate of xi strictly positive. Their actual images are affinely independent. The chart dimension equals the affine dimension of F, and its linear range lies in ker(u). The old chart_boundary theorem identifies the unit contacts as original pure points under the full original hypotheses.")),
                Paragraph(Text("Place a small affine simplex around xi inside the open unit ball. Every vertex differs from xi, since all its barycentric coordinates at xi are positive. Continuity along each outward ray supplies a unit-sphere point. Divide the old positive weights by their positive radial factors and normalize their sum. These weights reconstruct xi from the new sphere points. Their affine span contains xi and each old basis vertex, so it is full; the exact number of vertices gives affine independence. The construction includes segment balls and xi=0."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("sector-violation"), DeclarationHandle.Create(Owner + "sectorViolation"),
            H("Additional common-sector condition"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("Every one of the fixed dim(a)+1 source sectors has a nonzero original normal b, nonnegative on all of C and vanishing at the same actual t, with nonzero actual source slope, direction within theta of that sector, and norm(g_b)>H M(b) alpha_F(t). This is Q133.14 at one index. Its eventual sequence version is an extra antecedent and is not derived from exclusion balls, positive lifts or local pure-limit density. Normalized contrast is allowed to tend to zero."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("uniform-return-sectors"), DeclarationHandle.Create(Owner + "uniform_return_sectors"),
            H("One sector for every original normal"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(
                Paragraph(Text("There are epsilon, theta and H>0 before all r,t,b. For every actual pure return r,t with r near y and affine dimension of D(t) at most dim(a), one index i works simultaneously for every original nonzero positive annihilator b of t: a nonzero slope whose direction lies in sector i satisfies norm(g_b)<=H M(b) alpha_F(t). The quantifiers are constants, all r,t, one i, all b. There is no per-normal choice of i.")),
                Paragraph(Text("The old positive_annihilator_maximum supplies a pure global maximizer x in the same D(t). Choose a nearest source point a(q), norm(q)<=1. With s=norm(g_b)>0 and w=g_b/s, the global maximum and the dual bound give s(1-inner(w,q))<=A M(b) alpha. Hence norm(q-w)^2<=2 A M(b) alpha/s, and norm(x-a(v_i))<=alpha+norm(T_F)(sqrt(2 A M(b) alpha/s)+norm(w-v_i)). No division by alpha is made; the alpha=0 case is included. Zero slope lies outside the implication.")),
                Paragraph(Text("Positive barycentric reconstruction is stable for perturbed contacts and a nearby returned point in one common affine space of dimension at most dim(a). A fixed affine left inverse of the source chart reduces the perturbation to a fixed parameter space. Invert the perturbed affine interpolation map, obtain positive coordinates, prove actual reconstruction, and use rank counting to identify the common affine space. If every sector failed, pure maximizers in the same D(t) would be close to all source contacts and reconstruct r with strictly positive weights. Since dim(a)>=1, affine independence and extremality of r contradict this. All constants are fixed before the return and normal families."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("source-projection"), DeclarationHandle.Create(Owner + "sourceProjection"),
            H("Orthogonal projection onto the source affine space"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("In any chosen Euclidean metric on V, this is the affine orthogonal projection onto aff(F), expressed using the source center and the orthogonal projection onto U=direction(aff(F)). It fixes aff(F), maps every point into aff(F), and contracts distances to every point of aff(F)."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("projected-linear"), DeclarationHandle.Create(Owner + "projectedLinear"),
            H("Actual projected return operator"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("For any whole return chart c+L closedBall(d), A is proj_U composed with L, with codomain restricted to U. Its kernel J is the kernel of this actual projected operator. J is not identified with ker(L), because the original L is injective."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("singular-tail"), DeclarationHandle.Create(Owner + "singularTail"),
            H("Ordered right singular tail"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("For an actual real return operator L, use the pinned native orthonormal eigenbasis of L adjoint composed with L, ordered by decreasing eigenvalue. W is the span of directions with zero-based index at least k. It equals the orthogonal complement of the first k directions. Within tied eigenspaces the native basis makes a choice; every estimate uses only sorted spectral inequalities, so it remains valid at ties. The definition exists for every early dimension: when k>=d the tail is zero, without asserting that the eventual bounds already hold."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("original-return-geometry"), DeclarationHandle.Create(Owner + "original_return_geometry"),
            H("Dimension escape and positive intrinsic singular-tail mass"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(
                Paragraph(Text("There are fixed positive epsilon, theta, H, beta and eta, with beta<R=diam(K)/2, depending only on the source data and K, before every sequence and every return chart. These constants satisfy the full sector bound. For any actual sequence r_n tending to y, t_n in P intersected with D(r_n), and the explicit eventual common-sector condition, alpha_n tends to zero. Every supplied whole injective chart of D(t_n), and every actual coordinate z_n mapping to r_n, has norm(z_n)=1, positive dimension d_n<=dim(ker(u)), and norm(L_n)<=R. Eventually d_n>=dim(a)+1.")),
                Paragraph(Text("The same original pure maximizers give contacts near the fixed source simplex. Project them orthogonally into aff(F). A second stability result in that fixed affine space supplies one closed relative ball B_aff(F)(y,beta) contained in their convex hull and hence in the projected whole D(t_n), at every sufficiently large index. This uses reconstruction and a full affine inverse, rather than openness alone. Antipodal chart endpoints in K give the global operator bound R. Original zero symmetry and chart_boundary give the actual unit coordinates.")),
                Paragraph(Text("Write e_n=dist(r_n,y), A_n=proj_U composed with L_n and J_n=ker(A_n). Eventually e_n<beta and the projected ball supplies a radius rho=beta-e_n ball about A_n z_n inside A_n(closedBall(0,1)). Let w be the orthogonal projection of z_n onto J_n perpendicular. For w!=0, move outward from A_n w by rho, take a genuine unit-ball preimage, and use uniqueness of the orthogonal minimum-norm preimage. With norm(A_n)<=R this proves norm(w)<=1-rho/R. The w=0 branch is included. Pythagoras gives the actual finite bound norm(proj_J_n z_n)^2>=1-(1-(beta-e_n)/R)^2.")),
                Paragraph(Text("The projected relative ball gives beta norm(h)<=norm(L_n adjoint h) for every h in U, by testing its two antipodal points and using actual chart preimages. The nearest source point and both chart endpoints give norm(proj_U_perp composed with L_n)<=alpha_n. Native ordered real spectral coordinates and dimension counting then prove beta<=sigma_k(L_n) and sigma_(k+1)(L_n)<=alpha_n at every sufficiently large index. Here source sigma_k is Lean index dim(a)-1, and source sigma_(k+1) is Lean index dim(a). The fixed kept constant s_*=beta is chosen before all sequences and charts.")),
                Paragraph(Text("For v in J_n, L_n v is entirely normal to U, so beta norm(proj_T_n v)<=alpha_n norm(v), where T_n is the span of the first k ordered right singular directions. Apply this to proj_J_n z_n, use orthogonal decomposition and Cauchy-Schwarz, and include the zero-vector branch. This gives norm(proj_J_n z_n)<=norm(proj_W_n z_n)+alpha_n/beta. Combine it with the actual radial kernel margin. Put gamma=1-(1-beta/(2R))^2 and eta=gamma/4>0. Eventually dist(r_n,y)<beta/2 and alpha_n/beta<sqrt(gamma)/2, hence norm(proj_W_n z_n)^2>=eta. The unit bound supplies the upper boundedness needed for the real liminf. Thus liminf sigma_k>=s_*>0 and liminf norm(proj_W_n z_n)^2>=eta>0. No constant-dimension extraction, frame convergence or inference from shrinking physical axes is used. The private real eigenbasis leaf estimates adapt TauCeti revision 62bbc0596dc3539d488232e4e924a338548ea0a9, with original copyright and the existing full Apache license retained. These reusable proof ingredients carry no new-content claim."))), DescribeRole.Theorem),
        Paragraph(Text("No actual pure sequence satisfying the common-sector condition is constructed. These results do not establish local pure-limit density, existence of a common positive lift, an equivalence with fixed-test lifting, a collapse theorem or a full original-domain countermodel. They do not assume or conclude that y lies outside closure(P). Vanishing physical axis lengths alone do not imply vanishing unit-ball parameters. These are conditional mathematical results, without a physical-realization or literature-priority claim.")))));
}
